def NBitBinary(N):
    def backtrack(s, ones, zeros):
        if len(s) == N:
            result.append(s)
            return
        if ones < N:
            backtrack(s + '1', ones + 1, zeros)
        if zeros < ones:
            backtrack(s + '0', ones, zeros + 1)

    result = []
    backtrack('', 0, 0)
    return sorted(result, reverse=True)
